INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29h-2017-q01','exam-sg','ISMS・リーダーシップ','standard','single_choice','【2017年度 平成29年春期 午前 問1】JIS Q 27001:2014（情報セキュリティマネジメントシステム－要求事項）において，ISMSに関するリーダーシップ及びコミットメントをトップマネジメントが実証する上で行う事項として挙げられているものはどれか。','[{"id":"a","text":"ISMSの有効性に寄与するよう人々を指揮し，支援する。"},{"id":"b","text":"ISMSを組織の他のプロセスと分けて運営する。"},{"id":"c","text":"情報セキュリティ方針に従う。"},{"id":"d","text":"情報セキュリティリスク対応計画を策定する。"}]','"a"','正解はア。トップマネジメントはISMSの有効性に向けて人々を指揮・支援し，組織のプロセスに統合して運用する責任を負う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q02','exam-sg','サプライチェーン・リスク管理','standard','single_choice','【2017年度 平成29年春期 午前 問2】経済産業省とIPAが策定した「サイバーセキュリティ経営ガイドライン（Ver 1.1）」が，自社のセキュリティ対策に加えて，実施状況を確認すべきとしている対策はどれか。','[{"id":"a","text":"自社が提供する商品及びサービスの個人利用者が行うセキュリティ対策"},{"id":"b","text":"自社に出資している株主が行うセキュリティ対策"},{"id":"c","text":"自社のサプライチェーンのビジネスパートナが行うセキュリティ対策"},{"id":"d","text":"自社の事業所近隣の地域社会が行うセキュリティ対策"}]','"c"','正解はウ。自社だけでなく，サプライチェーンを構成するビジネスパートナーのセキュリティ対策状況も確認することが重要である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q03','exam-sg','インシデント対応体制','standard','single_choice','【2017年度 平成29年春期 午前 問3】組織的なインシデント対応体制の構築を支援する目的でJPCERT/CCが作成したものはどれか。','[{"id":"a","text":"CSIRTマテリアル"},{"id":"b","text":"ISMSユーザーズガイド"},{"id":"c","text":"証拠保全ガイドライン"},{"id":"d","text":"組織における内部不正防止ガイドライン"}]','"a"','正解はア。CSIRTマテリアルは，組織内のインシデント対応チーム（CSIRT）の構築・運用を支援する資料である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q04','exam-sg','事業継続・RPO','standard','single_choice','【2017年度 平成29年春期 午前 問4】ディザスタリカバリを計画する際の検討項目の一つであるRPO（Recovery Point Objective）はどれか。','[{"id":"a","text":"業務の継続性を維持するために必要な人員計画と要求される交代要員のスキルを示す指標"},{"id":"b","text":"災害発生時からどのくらいの時間以内にシステムを再稼働しなければならないかを示す指標"},{"id":"c","text":"災害発生時に業務を代替する遠隔地のシステム環境と，通常稼働しているシステム環境との設備投資の比率を示す指標"},{"id":"d","text":"システムが再稼働したときに，災害発生前のどの時点の状態までデータを復旧しなければならないかを示す指標"}]','"d"','正解はエ。RPOは目標復旧時点を表し，障害発生時にどこまで遡ったデータを復旧する必要があるかを示す。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q05','exam-sg','リスクマネジメント','standard','single_choice','【2017年度 平成29年春期 午前 問5】JIS Q 31000:2010（リスクマネジメント－原則及び指針）において，リスクマネジメントを効果的なものにするために，組織が順守することが望ましい原則はどれか。','[{"id":"a","text":"リスクマネジメントは静的であり，変化が生じたときに終了する。"},{"id":"b","text":"リスクマネジメントは組織に合わせて作られる。"},{"id":"c","text":"リスクマネジメントは組織の主要なプロセスから分離した単独の活動である。"},{"id":"d","text":"リスクマネジメントはリスクが顕在化した場合を対象とする。"}]','"b"','正解はイ。リスクマネジメントは組織の状況に合わせて設計され，意思決定や主要な業務プロセスに組み込まれる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q06','exam-sg','リスクマネジメント','standard','single_choice','【2017年度 平成29年春期 午前 問6】JIS Q 31000:2010（リスクマネジメント－原則及び指針）におけるリスクマネジメントプロセスを構成する活動の実行順序として，適切なものはどれか。','[{"id":"a","text":"リスク特定 → リスク対応 → リスク分析 → リスク評価"},{"id":"b","text":"リスク特定 → リスク分析 → リスク評価 → リスク対応"},{"id":"c","text":"リスク評価 → リスク特定 → リスク分析 → リスク対応"},{"id":"d","text":"リスク評価 → リスク分析 → リスク特定 → リスク対応"}]','"b"','正解はイ。リスクを特定し，分析・評価した後に，評価結果に応じた対応を選択する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q07','exam-sg','ISMS・リスク用語','standard','single_choice','【2017年度 平成29年春期 午前 問7】JIS Q 27000:2014（情報セキュリティマネジメントシステム－用語）における「リスクレベル」の定義はどれか。','[{"id":"a","text":"脅威によって付け込まれる可能性のある，資産又は管理策の弱点"},{"id":"b","text":"結果とその起こりやすさの組合せとして表現される，リスクの大きさ"},{"id":"c","text":"対応すべきリスクに付与する優先順位"},{"id":"d","text":"リスクの重大性を評価するために目安とする条件"}]','"b"','正解はイ。リスクレベルは，結果と発生可能性の組合せで表現されるリスクの大きさである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q08','exam-sg','委託先管理・インシデント対応','standard','single_choice','【2017年度 平成29年春期 午前 問8】A社は情報システムの運用をB社に委託している。当該情報システムで発生した情報セキュリティインシデントへの対応として，適切なものはどれか。','[{"id":"a","text":"委託契約継続の可否及び再発防止策の決定をB社に任せる。"},{"id":"b","text":"SLAに緊急時のセキュリティ手続を記載せず，B社の裁量に任せる。"},{"id":"c","text":"あらかじめ定めた連絡経路に従って，B社からA社及びB社の関係者へ迅速に連絡する。"},{"id":"d","text":"事前に定めた対応手順よりも，経験豊かなB社担当者の判断を常に優先する。"}]','"c"','正解はウ。委託業務のインシデントでも，事前に合意した連絡経路と手順に従って迅速に報告・対応する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q09','exam-sg','暗号技術','standard','single_choice','【2017年度 平成29年春期 午前 問9】暗号の危殆化に該当するものはどれか。','[{"id":"a","text":"暗号化通信を行う前に，データの伝送速度や暗号の設定情報などを交換すること"},{"id":"b","text":"考案当時は容易に解読できなかった暗号アルゴリズムが，コンピュータ性能の向上などによって解読されやすい状態になること"},{"id":"c","text":"自身が保有する鍵を使って，暗号化されたデータから元のデータを復元すること"},{"id":"d","text":"元のデータから一定の計算手順に従って疑似乱数を求め，元のデータをその疑似乱数に置き換えること"}]','"b"','正解はイ。計算能力の向上や暗号解読技術の進歩によって，従来安全だった暗号が安全性を失うことを危殆化という。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja'),
('sg-official-h29h-2017-q10','exam-sg','電子署名・タイムスタンプ','standard','single_choice','【2017年度 平成29年春期 午前 問10】情報セキュリティにおけるタイムスタンプサービスの説明はどれか。','[{"id":"a","text":"公式の記録で使われる全世界共通の日時情報を，暗号化通信で安全に表示するWebサービス"},{"id":"b","text":"生体情報を認証システムに登録した日時を用いて認証するサービス"},{"id":"c","text":"電子データがある日時に確かに存在していたこと，及びその日時以降に改ざんされていないことを証明するサービス"},{"id":"d","text":"ネットワーク上のPCやサーバの時計を合わせるための日時情報を，改ざんされないよう通知するサービス"}]','"c"','正解はウ。タイムスタンプは電子データの存在時刻と，その後に改ざんされていないことを証明する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fzx1-att/2017h29h_sg_am_qs.pdf','ja');
